47	template<typename Operator>
48	__device__ __forceinline__ float warp_reduce_acc(float &val, Operator &op) {
49	    // Get the thread's position within its group of 4
50	    const int group_id = threadIdx.x / 4;     // Which group of 4 this thread belongs to
51	    const int local_id = threadIdx.x % 4;     // Position within group of 4 (0-3)
52	    
53	    // Only reduce within groups of 4 threads
54	    // Using butterfly pattern
55	    #pragma unroll
56	    for (int offset = 2; offset > 0; offset >>= 1) {
57	        float other = __shfl_down_sync(0xffffffff, val, offset);
58	        if (local_id < offset) {
59	            val = op(val, other);
60	        }
61	    }
62	
63	    // Broadcast the result from thread 0 to all threads in the group
64	    val = __shfl_sync(0xffffffff, val, group_id * 4);
65	    
66	    return val;
67	}
