120	template<typename Engine0, typename Layout0, typename Engine1, typename Layout1, typename Tensor2, typename Operator>
121	__device__ __forceinline__ void quad_allreduce_(Tensor<Engine0, Layout0> &dst, Tensor<Engine1, Layout1> &src, Tensor2 &reduce_tmp, Operator &op) {
122	    // __shared__ float smem[4];  // For 4 warps, we need 4 elements
123	    CUTE_STATIC_ASSERT_V(size(dst) == size(src));
124	    
125	    const int warp_id = threadIdx.x / 32;
126	    const int lane_id = threadIdx.x % 32;
127	    
128	    #pragma unroll
129	    for (int i = 0; i < size(dst); i++) {
130	        // First do reduction within each group of 4 threads
131	        float val = Allreduce<4>::run(src(i), op);
132	        
133	        // Write the result to shared memory for each group's leader
134	        if (lane_id % 4 == 0) {
135	            reduce_tmp(i,warp_id) = val;
136	        }
137	        __syncthreads();
138	        
139	        // First thread in the first group reads all values and reduces them
140	        if (lane_id == 0) {
141	            float final_val = reduce_tmp(0,0);
142	            #pragma unroll
143	            for (int w = 1; w < 4; w++) {  // For 4 warps
144	                final_val = op(final_val, reduce_tmp(i,w));
145	            }
146	            // Write back the final result
147	            reduce_tmp(i,0) = final_val;
148	        }
149	        __syncthreads();
150	        
151	        // All threads read the final result
152	        // cute::copy(reduce_tmp(0,0), dst(i));
153	        dst(i) = reduce_tmp(i,0);
154	    }
155	}
