48	template<typename Tensor0, typename Tensor1, typename Tensor2, typename Operator>
49	CUTE_DEVICE
50	void allreduce_(Tensor0 &dst, Tensor1 &src, Tensor2 &reduce_tmp, Operator &op) {
51	    CUTE_STATIC_ASSERT_V(size(dst) == size(src));
52	
53	    const int warp_id = threadIdx.x / 32;
54	    const int lane_id = threadIdx.x % 32;
55	    
56	    #pragma unroll
57	    for (int i = 0; i < size(dst); i++) {
58	        // First do reduction within each group of 4 threads
59	        float val = quant::warp_reduce(src(i), op);
60	        // Write the result to shared memory for each group's leader
61	        if (lane_id < 4) {
62	            reduce_tmp(i,warp_id * 4 + lane_id) = val;
63	        }
64	        __syncthreads();
65	        
66	        // First thread in the first group reads all values and reduces them
67	        if (lane_id < 4) {
68	            float final_val = reduce_tmp(i,0 + lane_id);
69	            #pragma unroll
70	            for (int w = 1; w < 4; w++) {  // For 4 warps
71	                final_val = op(final_val, reduce_tmp(i,w * 4 + lane_id));
72	            }
73	            // Write back the final result
74	            reduce_tmp(i, 0 + lane_id) = final_val;
75	        }
76	        __syncthreads();
77	        
78	        // All threads read the final result
79	        dst(i) = reduce_tmp(i,0 + lane_id % 4);
80	
81	    }
82	
83	    
84	}
