380	void quant_Ktensor(Tensor1 &src, Tensor2 &dst, 
381	                   TensorParamsG1 &scales_k_g, TensorParamsG2 &zeros_k_g, 
382	                   const int num_params) {
383	
384	    const int num_bits = 4;
385	
386	    const float max_val  = float((1 << num_bits) - 1);
387	    // const int num_params = 128 / group_size;
388	    const int ki         = size<2>(src) / num_params;
389	
390	    // Declare per-channel tensors
391	    using TensorChannel = decltype(make_fragment_like<float>(scales_k_g));
392	    TensorChannel channel_max, channel_min, channel_range, channel_scales_inv, channel_zeros;
393	
394	    CUTE_UNROLL
395	    for (int k = 0; k < size<1>(src); ++k) {
396	        quant::reduce_max_g(src(_, k, _), channel_max, k, num_params); // TODO:check 128
397	        quant::reduce_min_g(src(_, k, _), channel_min, k, num_params);
398	    }
399	
400	    // Compute per-channel scale inverses and zeros
401	    CUTE_UNROLL
402	    for (int i = 0; i < size(channel_max); ++i) {
403	        float max_i = float(channel_max(i));
404	        float min_i = float(channel_min(i));
405	        float range = max_i - min_i;
406	        // Avoid division by zero
407	        float scale_inv = (range > 0.0f) ? (max_val / range) : 0.0f;
408	        channel_scales_inv(i) = scale_inv;
409	        channel_zeros(i)      = min_i;
410	        // Store scales and zeros
411	        scales_k_g(i)         = scale_inv == 0 ? 0.0f : 1.0f / scale_inv;  // Store actual scale
412	        zeros_k_g(i)          = min_i;
413	    }
414	
415	    // Pack the tensor
416	    CUTE_UNROLL
417	    for (int k = 0; k < size<2>(src); ++k) {
418	
419	        CUTE_UNROLL
420	        for (int i = 0; i < size<0>(src); ++i) {
421	
422	            CUTE_UNROLL
423	            for (int jj = 0; jj < size<1>(src); jj += 4) {
424	                float zero0 = float(channel_zeros(k / ki + jj + 0 * num_params));
425	                float zero1 = float(channel_zeros(k / ki + jj + 1 * num_params));
426	                float zero2 = float(channel_zeros(k / ki + jj + 2 * num_params));
427	                float zero3 = float(channel_zeros(k / ki + jj + 3 * num_params));
428	
429	                float scale_inv0 = float(channel_scales_inv(k / ki + jj + 0 * num_params));
430	                float scale_inv1 = float(channel_scales_inv(k / ki + jj + 1 * num_params));
431	                float scale_inv2 = float(channel_scales_inv(k / ki + jj + 2 * num_params));
432	                float scale_inv3 = float(channel_scales_inv(k / ki + jj + 3 * num_params));
433	
434	                // float val0 = float(src(i, jj, k));
435	                // float val1 = float(src(i, jj + 1, k));
436	                // float val2 = float(src(i, jj + 2, k));
437	                // float val3 = float(src(i, jj + 3, k));
438	                
439	                float val0 = float(src(i, jj, k)) - zero0;
440	                float val1 = float(src(i, jj + 1, k)) - zero1;
441	                float val2 = float(src(i, jj + 2, k)) - zero2;
442	                float val3 = float(src(i, jj + 3, k)) - zero3;
443	
444	                val0 *= scale_inv0;
445	                val1 *= scale_inv1;
446	                val2 *= scale_inv2;
447	                val3 *= scale_inv3;
448	
449	                // Round and clamp the values
450	                val0 = fminf(fmaxf(roundf(val0), 0.0f), max_val);
451	                val1 = fminf(fmaxf(roundf(val1), 0.0f), max_val);
452	                val2 = fminf(fmaxf(roundf(val2), 0.0f), max_val);
453	                val3 = fminf(fmaxf(roundf(val3), 0.0f), max_val);
454	
455	                // Pack the 4 quantized values into a 16-bit integer
456	                uint16_t packed = 0;
457	                packed |= (static_cast<uint16_t>(static_cast<uint8_t>(val3)) & 0xF);
458	                packed <<= 4;
459	                packed |= (static_cast<uint16_t>(static_cast<uint8_t>(val2)) & 0xF);
460	                packed <<= 4;
461	                packed |= (static_cast<uint16_t>(static_cast<uint8_t>(val1)) & 0xF);
462	                packed <<= 4;
463	                packed |= (static_cast<uint16_t>(static_cast<uint8_t>(val0)) & 0xF);
464	
465	                // Store the packed value
466	                dst(i, jj / 4, k) = packed;
467	            }
468	        }
469	    }
